// Fold every probe into ONE verdict, so one Healthchecks check covers N
// subjects (the box-report-ran argument: 1 check, 17 things). The reason text
// travels into the alert, so a red says WHAT broke without an SSH session.
//
// A probe that cannot answer at all must read as a problem, never as a pass —
// `neverError` turns non-2xx into data, and `onError: continueRegularOutput`
// turns a timeout, a DNS failure or a refused login into an item with no
// result. Both land here as problems rather than as silence.
//
// THRESHOLDS LIVE HERE, NOT IN SQL. monitoring.health returns raw counts and
// ages on purpose: retuning a number in a view means running DDL against the
// pilot database, which is expensive enough that nobody does it, and a monitor
// nobody retunes gets muted instead. Every limit below is one edit away.
const problems = [];
const notes = [];

const mins = (s) => Math.round(s / 60) + 'm';
const hours = (s) => (s / 3600).toFixed(1) + 'h';

// ── probe 1: the web service ────────────────────────────────────────────────
// /health is unauthenticated and routed BEFORE the auth check and the IP
// allowlist, on purpose: a health check that only answers while everything else
// is healthy is not a health check. So the status code doubles as a build
// fingerprint:
//   200 -> current branch is deployed; body carries {commit, checks.db}, and
//          the probe has silently upgraded from "is it up" to "is it working".
//   401 -> alive, but the deployed commit PREDATES /health, so auth answered
//          first. Liveness only. Not an incident — it is the known commit drift.
//   503 -> /health ran and the DB round-trip failed. Real incident.
let web = null;
try {
  web = $('Probe web /health').first().json;
} catch (err) {
  web = null;
}
const code = web && typeof web.statusCode === 'number' ? web.statusCode : null;
if (code === null) {
  const why = (web && (web.error || web.message)) || 'no response';
  problems.push('web: unreachable (' + String(why).slice(0, 120) + ')');
} else if (code === 200) {
  const body = (web && web.body) || {};
  const db = (body.checks && body.checks.db) || 'unknown';
  const commit = String(body.commit || 'unknown').slice(0, 7);
  if (db !== 'ok') {
    problems.push('web: /health says db=' + db + ' (commit ' + commit + ')');
  } else {
    notes.push('web 200 db=ok commit=' + commit);
  }
} else if (code === 401) {
  // TIGHTENED 2026-08-27, after prod first answered 200. Before the deploy this
  // was a pass, because /health did not exist in the live build and the drift
  // was known. Now that it does, a 401 can only mean the deployed code LOST it —
  // a rollback to a pre-/health commit, or auth moving in front of a route that
  // is unauthenticated on purpose. Both are regressions, so both go red.
  problems.push('web: /health answered 401 — deployed build has no /health (rollback?) or auth moved in front of it');
} else {
  problems.push('web: HTTP ' + code);
}

// ── probe 2: the workers, via monitoring.health ─────────────────────────────
// This is the only probe that can answer "is it DOING its job". From outside a
// worker, "zero rows processed because none arrived" and "zero rows processed
// because it is wedged" are the same observation; only our own data separates
// them.
let row = null;
try {
  row = $('Query pilot DB').first().json;
} catch (err) {
  row = null;
}

if (!row || row.observed_at === undefined) {
  const why = (row && (row.error || row.message)) || 'no row returned';
  problems.push('db: monitoring.health unreadable (' + String(why).slice(0, 140) + ')');
} else {
  // NULL means the relevant set is EMPTY (no pending calls, no captures yet) —
  // "nothing to say", never zero. Comparing null numerically would silently read
  // as 0 and turn every quiet period into a pass on a check that never ran.
  const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
  const over = (v, limit, msg) => {
    const n = num(v);
    if (n !== null && Number.isFinite(n) && n > limit) problems.push(msg(n));
  };

  // Calls-worker stalled: something is waiting and nothing is taking it.
  over(row.calls_pending_oldest_s, 900, (n) => 'calls-worker stalled: oldest pending ' + mins(n));

  // The strongest wedge evidence there is — a worker CLAIMED this row and never
  // finished, so it cannot be explained away by an empty inbox. Given a wide
  // grace because transcription legitimately takes minutes.
  over(row.calls_processing_oldest_s, 1800, (n) => 'calls-worker wedged: a row has been processing ' + mins(n));

  over(row.calls_error_1h, 3, (n) => 'call pipeline erroring: ' + n + ' in the last hour');
  over(row.calls_max_attempts, 4, (n) => 'retry storm: a call is on attempt ' + n);

  // Any non-zero value is a retention-promise breach, so there is no threshold
  // to tune: audio past its delete date, not deleted, not on legal hold.
  over(row.calls_purge_backlog, 0, (n) => 'Calls-purge stopped: ' + n + ' recording(s) past their delete date');

  // ── lifecycle-heart ───────────────────────────────────────────────────────
  // Read from the cron's OWN execution record (lifecycle_runs), not from the
  // cost rollup. The rollup was a proxy, and a proxy answers the question you
  // asked only for as long as nothing else can move it.
  //
  // Two ages, because a tick that runs and FAILS still writes a row: "when did
  // it last run" alone would report a cron failing every five minutes as
  // perfectly healthy. That is the same reason worker_heartbeats carries both
  // beat_at and last_ok_at.
  const runAge = num(row.lifecycle_run_age_s);
  const okAge = num(row.lifecycle_ok_age_s);
  if (row.lifecycle_run_age_s === undefined) {
    notes.push('lifecycle: view predates lifecycle_runs (migration not applied)');
  } else if (runAge === null) {
    // Table present, no rows. Could be freshly migrated or could be a dead cron,
    // and from here those look identical — so it is a note, and gross death is
    // still caught by the rollup check below.
    notes.push('lifecycle: no runs recorded yet');
  } else {
    // Cron is */5. Fifteen minutes is three consecutive missed ticks.
    over(row.lifecycle_run_age_s, 900, (n) => 'lifecycle-heart stopped: last tick ' + mins(n) + ' ago');
    if (okAge === null) {
      problems.push('lifecycle-heart has ticks but NONE succeeded');
    } else {
      over(row.lifecycle_ok_age_s, 1800, (n) => 'lifecycle-heart failing every tick: last clean tick ' + mins(n) + ' ago');
    }
  }

  // Demoted to what it actually measures. The cron ticks every 5 minutes but the
  // heavy sweeps self-gate to quarter-hour ticks, so a stale rollup while ticks
  // keep succeeding means the HEAVY sweep specifically has stopped — a real and
  // distinct failure, just not "the cron is dead". Two hours is eight missed
  // quarter-hour sweeps.
  over(row.cost_rollup_age_s, 7200, (n) => 'cost rollup stale: heavy sweep ' + mins(n) + ' behind');

  over(row.nudges_queued_oldest_s, 3600, (n) => 'nudge delivery stalled: oldest queued ' + mins(n));

  // The escalation sweep hands a nudge to the manager after 48h by default. 72h
  // means the deadline passed a full day ago and nothing moved. Deliberately not
  // mirroring NUDGE_ESCALATE_HOURS — a monitor that tracks a code constant
  // breaks quietly when the constant changes.
  over(row.nudges_asked_oldest_s, 259200, (n) => 'nudge escalation stalled: oldest asked ' + hours(n));

  // Wide on purpose. This is a small pilot; 24h of silence was the FIRST reading
  // we ever took, so a tight limit would have paged on day one, and a monitor
  // that cries wolf immediately gets muted. Tighten once we have a week of
  // baseline.
  over(row.l1_capture_age_s, 172800, (n) => 'no L1 capture in ' + hours(n));

  const pend = num(row.calls_pending);
  const proc = num(row.calls_processing);
  notes.push('db ok (calls ' + (pend === null ? 0 : pend) + 'p/' + (proc === null ? 0 : proc) + 'r)');

  // ── headless workers, via worker_heartbeats ───────────────────────────────
  // `workers` is one entry per process that has ever reported:
  //   {"board-worker": {beat_age_s, ok_age_s, work_age_s, detail}}
  // Thresholds are per service with a default, so adding a worker needs a row —
  // not a migration, and not a new Healthchecks check.
  //
  // undefined (not null) means the view PREDATES this column, i.e. the migration
  // has not been applied yet. That is a deployment state, not an incident, so it
  // is a note — this lets the workflow ship before the DDL lands.
  const LIMITS = { _default: { beat: 300, ok: 900 } };
  // Workers we require to exist. Deliberately EMPTY until a worker has actually
  // been deployed with heartbeat code: listing one before it ships would put the
  // check permanently red and train everyone to ignore it. Add 'board-worker'
  // here once its deploy is confirmed — that catches "never reported at all",
  // which is the one case staleness cannot, since a row that was never written
  // cannot go stale.
  const EXPECTED = [];

  if (row.workers === undefined) {
    notes.push('workers: view predates worker_heartbeats (migration not applied)');
  } else {
    const w = row.workers || {};
    for (const name of EXPECTED) {
      if (!w[name]) problems.push('worker ' + name + ' has NEVER reported');
    }
    for (const name of Object.keys(w)) {
      const lim = LIMITS[name] || LIMITS._default;
      const beat = num(w[name].beat_age_s);
      const okAge = num(w[name].ok_age_s);
      if (beat === null) {
        problems.push('worker ' + name + ': no beat recorded');
      } else if (beat > lim.beat) {
        problems.push('worker ' + name + ' stopped: last cycle ' + mins(beat) + ' ago');
      } else if (okAge === null) {
        // Cycling, but has never once completed without throwing. beat_at alone
        // would call this healthy — it is the swallowed-exception case.
        problems.push('worker ' + name + ' cycling but has NEVER completed a clean pass');
      } else if (okAge > lim.ok) {
        problems.push('worker ' + name + ' failing every cycle: last clean pass ' + mins(okAge) + ' ago');
      }
    }
    const live = Object.keys(w).length;
    if (live > 0) notes.push(live + ' worker(s) reporting');
  }
}

// ── probe 3: AssemblyAI (transcription vendor) ──────────────────────────────
// Public Statuspage, no credential. This is EXPLANATORY, not the impact signal:
// real transcription failures already surface as calls_error_1h from our own
// data. What this adds is "the calls pipeline is erroring AND the vendor has
// declared an outage", which turns a 2am page into a 2am decision.
//
// Only major/critical are treated as problems. A "minor" indicator is common,
// often unrelated to our endpoint, and paging on it would train the alert to be
// ignored — while costing nothing, because anything that actually breaks
// transcription shows up in our own error count regardless.
let aai = null;
try {
  aai = $('Probe AssemblyAI status').first().json;
} catch (err) {
  aai = null;
}
if (aai && aai.statusCode === 200 && aai.body && aai.body.status) {
  const ind = String(aai.body.status.indicator || 'unknown');
  const desc = String(aai.body.status.description || '').slice(0, 80);
  if (ind === 'major' || ind === 'critical') {
    problems.push('AssemblyAI ' + ind + ': ' + desc);
  } else if (ind !== 'none') {
    notes.push('AssemblyAI ' + ind);
  }
} else if (aai === null || aai.statusCode !== 200) {
  // Their status page being unreachable is not our incident. Note it so the
  // absence of an AssemblyAI verdict is visible rather than assumed healthy.
  notes.push('AssemblyAI status unavailable');
}

// ── probe 4: SignalWire account (the phone line) ────────────────────────────
// This is NOT the check we wanted. The gap was "credit running low", an early
// warning. SignalWire publishes no balance endpoint — verified live against the
// compatibility API (the account resource returns status/type, no balance) and
// against their documented endpoint index, which lists nothing for balance,
// billing, credit or usage. So this is the available substitute: the account's
// own status, which leaves "active" when the account is SUSPENDED for any
// reason — billing failure, fraud hold, ToS.
//
// Stated plainly because the difference matters operationally: this fires AFTER
// calls have already stopped, not before. It is worth having only because the
// alternative is nobody noticing at all, and a 5-minute-late alarm still beats
// hearing it from a customer.
//
// 401/403 is treated as a problem, not as "unreachable": both a rotated
// credential and a disabled account land there, and both need a human.
let sw = null;
try {
  sw = $('Probe SignalWire account').first().json;
} catch (err) {
  sw = null;
}
if (sw && sw.statusCode === 200) {
  const st = String((sw.body && sw.body.status) || 'unknown');
  if (st !== 'active') {
    problems.push('SignalWire account status=' + st + ' (calls will not work)');
  } else {
    notes.push('signalwire active');
  }
} else if (sw && (sw.statusCode === 401 || sw.statusCode === 403)) {
  problems.push('SignalWire rejected our credentials (HTTP ' + sw.statusCode + ') — rotated key or disabled account');
} else {
  // Their API being unreachable is not our incident, and must not read as a
  // pass. Note it so an absent verdict is visible.
  notes.push('signalwire status unavailable');
}

const ok = problems.length === 0;
return [{ json: { ok: ok, detail: ok ? notes.join('; ') : problems.join('; ') } }];
